import Foundation

// Codable mirrors of the JSON bundle in Data/ (generated by tools/generate-ios-data.mjs).

struct SpeciesFile: Codable {
    let generated: String
    let species: [Species]
}

struct Species: Codable, Identifiable, Hashable {
    let slug: String
    let name: String
    let sci: String
    let env: String
    let habitat: String
    let season: String
    let depth: String
    let baits: [String]
    let regions: [String]
    let aliases: [String]
    let img: String

    var id: String { slug }

    /// Absolute URL for the species photo on blueseasfishing.com (lazy-loaded).
    var imageURL: URL? {
        let path = img.hasPrefix("http") ? img : "https://www.blueseasfishing.com\(img)"
        return img.isEmpty ? nil : URL(string: path)
    }

    var letter: String { String(name.prefix(1)).uppercased() }
}

struct ComparisonsFile: Codable {
    let comparisons: [Comparison]
}

struct Comparison: Codable, Identifiable, Hashable {
    let slug: String
    let a: String
    let b: String
    let env: String
    let lede: String
    let rows: [ComparisonRow]

    var id: String { slug }
    var title: String { "\(a) vs. \(b)" }
}

struct ComparisonRow: Codable, Hashable {
    let feature: String
    let a: String
    let b: String
}

struct DestinationsFile: Codable {
    let destinations: [Destination]
}

struct Destination: Codable, Identifiable, Hashable {
    let slug: String
    let name: String
    let count: Int
    let species: [String]

    var id: String { slug }
}
